select date_format('1970-01-01 08:00:00' + interval floor(`c`.`last_seen`) second,'%Y/%m/%d %H:%i:%s') AS `时间`,coalesce(nullif(`c`.`source_ip`,''),'未识别') AS `源 IP`,case when `c`.`source_ip` is null or `c`.`source_ip` = '' then '未识别' else coalesce(nullif(`g`.`location`,''),'未查询') end AS `IP归属地`,case when `c`.`source_peer` = '172.30.3.3' and (`c`.`node` is null or `c`.`node` = '') then '172.30.3.3（云厂入口：203.0.113.103）' when `c`.`node` is null or `c`.`node` = '' then '未识别' when `r`.`node` is null then concat('未核验（',`c`.`node`,'）') when `r`.`tunnel_ip` is null then concat('直连（',`c`.`node`,'；未经过隧道）') else concat(`r`.`tunnel_ip`,'（',`c`.`node`,'）') end AS `隧道内网 IP（入口机器）`,`c`.`site` AS `目标网站`,case when `c`.`source_ip` is null or `c`.`source_ip` = '' or `v`.`interval_seconds` is null or `v`.`interval_seconds` <> 5 or `v`.`observed_at` <> `c`.`last_seen` or `v`.`upload_bps` is null then '未采样' when `v`.`upload_bps` < 1000000 then concat(cast(round(`v`.`upload_bps` / 1000,2) as decimal(22,2)),' KB/s') else concat(cast(round(`v`.`upload_bps` / 1000000,2) as decimal(22,2)),' MB/s') end AS `最近上传速率`,case when `c`.`source_ip` is null or `c`.`source_ip` = '' or `v`.`interval_seconds` is null or `v`.`interval_seconds` <> 5 or `v`.`observed_at` <> `c`.`last_seen` or `v`.`download_bps` is null then '未采样' when `v`.`download_bps` < 1000000 then concat(cast(round(`v`.`download_bps` / 1000,2) as decimal(22,2)),' KB/s') else concat(cast(round(`v`.`download_bps` / 1000000,2) as decimal(22,2)),' MB/s') end AS `最近下载速率` from (((select `c`.`connection_id` AS `connection_id`,`c`.`last_seen` AS `last_seen`,`c`.`source_peer` AS `source_peer`,`c`.`inbound_port` AS `inbound_port`,`c`.`site` AS `site`,`c`.`source_ip` AS `source_ip`,`c`.`node` AS `node`,row_number() over ( partition by case when `c`.`connection_id` is null or `c`.`source_ip` is null or `c`.`source_ip` = '' or `c`.`site` is null or `c`.`site` = '' or lcase(`c`.`site`) = 'unknown' or `c`.`node` is null or `c`.`node` = '' or `c`.`inbound_port` is null or `c`.`last_seen` is null then `c`.`connection_id` else `c`.`source_ip` end,`c`.`site`,case when `c`.`node` is null or `c`.`node` = '' then `c`.`connection_id` else `c`.`node` end,`c`.`inbound_port`,case when `c`.`last_seen` is null then `c`.`connection_id` else floor((`c`.`last_seen` + 2.5) / 5) end order by `c`.`last_seen` desc,`c`.`connection_id`) AS `_session_rank` from (select `region-a`.`connection_state`.`connection_id` AS `connection_id`,`region-a`.`connection_state`.`start_ts` AS `start_ts`,`region-a`.`connection_state`.`last_seen` AS `last_seen`,`region-a`.`connection_state`.`source_peer` AS `source_peer`,`region-a`.`connection_state`.`source_port` AS `source_port`,`region-a`.`connection_state`.`inbound_port` AS `inbound_port`,`region-a`.`connection_state`.`site` AS `site`,`region-a`.`connection_state`.`prev_up` AS `prev_up`,`region-a`.`connection_state`.`prev_down` AS `prev_down`,`region-a`.`connection_state`.`flow_id` AS `flow_id`,`region-a`.`connection_state`.`source_ip` AS `source_ip`,`region-a`.`connection_state`.`node` AS `node`,`region-a`.`connection_state`.`quality` AS `quality`,`region-a`.`connection_state`.`_seq` AS `_seq` from `region-a`.`connection_state` where `region-a`.`connection_state`.`last_seen` >= unix_timestamp() - 604800) `c`) `c` left join `region-a`.`connection_rates` `v` on(`v`.`connection_id` = `c`.`connection_id`)) left join `region-a`.`entry_routes` `r` on(`r`.`node` = `c`.`node` and `r`.`inbound_port` = `c`.`inbound_port`)) left join `region-a`.`ip_geo` `g` on(`g`.`source_ip` = `c`.`source_ip`) where `c`.`_session_rank` = 1 order by `c`.`last_seen` desc,`c`.`connection_id`
